suppressMessages(library(dplyr))
options(width=250)
u <- readRDS("data/municipal_elections/final/municipal_unharm.rds")
print(u %>% filter(ags %in% c("09473159","09181127","09274145","09373155")) %>% select(ags,ags_name,election_year,eligible_voters,number_voters,valid_votes,turnout) %>% arrange(ags,election_year) %>% as.data.frame)
by <- u %>% filter(state=="09") %>% arrange(ags,election_year) %>% group_by(ags) %>% mutate(r=eligible_voters/lag(eligible_voters),rn=eligible_voters/lead(eligible_voters)) %>% ungroup()
cat("BY turnout>0.9 by year\n"); print(by %>% filter(turnout>0.9) %>% count(election_year))
cat("BY eligible ratio <0.75 vs prev election, and >1.3 next, by year\n"); print(by %>% filter(r<0.75|rn>1.3) %>% count(election_year))
cat("BY 2020 eligible vs 2026: ratio distribution\n"); x <- by %>% filter(election_year==2020) %>% mutate(q=eligible_voters/lead(eligible_voters)); print(summary(x$q))
print(x %>% filter(q<0.7) %>% select(ags,ags_name,eligible_voters,q,turnout) %>% as.data.frame)
